void FreespacePlannerNode::onTimer()
{
  autoware_utils::StopWatch<std::chrono::milliseconds> stop_watch;

  scenario_ = scenario_sub_.take_data();
  if (!utils::is_active(scenario_)) {
    reset();
    return;
  }

  updateData();

  if (!isDataReady()) {
    return;
  }

  if (is_completed_) {
    partial_trajectory_.header = odom_->header;
    const auto stop_trajectory = utils::create_stop_trajectory(partial_trajectory_);
    trajectory_pub_->publish(stop_trajectory);
    return;
  }

  // Get current pose
  current_pose_.pose = odom_->pose.pose;
  current_pose_.header = odom_->header;

  if (current_pose_.header.frame_id == "") {
    return;
  }

  // Must stop before replanning any new trajectory
  const bool is_reset_required = !reset_in_progress_ && isPlanRequired();
  if (is_reset_required) {
    // Stop before planning new trajectory, except in a new parking cycle as the vehicle already
    // stops.
    if (!is_new_parking_cycle_) {
      const auto stop_trajectory = partial_trajectory_.points.empty()
                                     ? utils::create_stop_trajectory(current_pose_, get_clock())
                                     : utils::create_stop_trajectory(partial_trajectory_);
      trajectory_pub_->publish(stop_trajectory);
      debug_pose_array_pub_->publish(utils::trajectory_to_pose_array(stop_trajectory));
      debug_partial_pose_array_pub_->publish(utils::trajectory_to_pose_array(stop_trajectory));
    }

    reset();

    reset_in_progress_ = true;
  }

  if (reset_in_progress_) {
    const auto is_ego_stopped =
      utils::is_stopped(odom_buffer_, node_param_.th_stopped_velocity_mps);
    if (is_ego_stopped) {
      // Plan new trajectory
      planTrajectory();
      reset_in_progress_ = false;
    } else {
      // Will keep current stop trajectory
      RCLCPP_WARN_THROTTLE(
        get_logger(), *get_clock(), 1000,
        "Waiting for the vehicle to stop before generating a new trajectory.");
    }
  }

  // StopTrajectory
  if (trajectory_.points.size() <= 1) {
    is_new_parking_cycle_ = false;
    return;
  }

  // Update partial trajectory
  updateTargetIndex();
  partial_trajectory_ =
    utils::get_partial_trajectory(trajectory_, prev_target_index_, target_index_, get_clock());

  // Publish messages
  trajectory_pub_->publish(partial_trajectory_);
  debug_pose_array_pub_->publish(utils::trajectory_to_pose_array(trajectory_));
  debug_partial_pose_array_pub_->publish(utils::trajectory_to_pose_array(partial_trajectory_));

  is_new_parking_cycle_ = false;

  // Publish ProcessingTime
  autoware_internal_debug_msgs::msg::Float64Stamped processing_time_msg;
  processing_time_msg.stamp = get_clock()->now();
  processing_time_msg.data = stop_watch.toc();
  processing_time_pub_->publish(processing_time_msg);
}

bool is_active(const Scenario::ConstSharedPtr & scenario)
{
  if (!scenario) return false;

  const auto & s = scenario->activating_scenarios;
  return std::find(std::begin(s), std::end(s), Scenario::PARKING) != std::end(s);
}

void FreespacePlannerNode::updateData()
{
  occupancy_grid_ = occupancy_grid_sub_.take_data();

  {
    auto msgs = odom_sub_.take_data();
    for (const auto & msg : msgs) {
      onOdometry(msg);
    }
  }
}

void FreespacePlannerNode::onOdometry(const Odometry::ConstSharedPtr msg)
{
  odom_ = msg;

  odom_buffer_.push_back(msg);

  // Delete old data in buffer
  while (true) {
    const auto time_diff =
      rclcpp::Time(msg->header.stamp) - rclcpp::Time(odom_buffer_.front()->header.stamp);

    if (time_diff.seconds() < node_param_.th_stopped_time_sec) {
      break;
    }

    odom_buffer_.pop_front();
  }
}

bool FreespacePlannerNode::isPlanRequired()
{
  if (trajectory_.points.empty()) {
    return true;
  }

  if (node_param_.replan_when_obstacle_found && checkCurrentTrajectoryCollision()) {
    RCLCPP_DEBUG(get_logger(), "Found obstacle");
    return true;
  }

  if (node_param_.replan_when_course_out) {
    const bool is_course_out = utils::calc_distance_2d(trajectory_, current_pose_.pose) >
                               node_param_.th_course_out_distance_m;
    if (is_course_out) {
      RCLCPP_INFO(get_logger(), "Course out");
      return true;
    }
  }

  return false;
}

bool FreespacePlannerNode::checkCurrentTrajectoryCollision()
{
  algo_->setMap(*occupancy_grid_);

  const size_t nearest_index_partial = autoware::motion_utils::findNearestIndex(
    partial_trajectory_.points, current_pose_.pose.position);
  const size_t end_index_partial = partial_trajectory_.points.size() - 1;
  const auto forward_trajectory = utils::get_partial_trajectory(
    partial_trajectory_, nearest_index_partial, end_index_partial, get_clock());

  const bool is_obs_found =
    algo_->hasObstacleOnTrajectory(utils::trajectory_to_pose_array(forward_trajectory));

  if (!is_obs_found) {
    obs_found_time_ = {};
    return false;
  }

  if (!obs_found_time_) obs_found_time_ = get_clock()->now();

  return (get_clock()->now() - obs_found_time_.get()).seconds() > node_param_.th_obstacle_time_sec;
}

void AbstractPlanningAlgorithm::setMap(const nav_msgs::msg::OccupancyGrid & costmap)
{
  costmap_ = costmap;

  const uint32_t nb_of_cells = costmap_.data.size();
  // Initialize status
  std::vector<bool> is_obstacle_table;
  is_obstacle_table.resize(nb_of_cells);
  for (uint32_t i = 0; i < nb_of_cells; ++i) {
    const int cost = costmap_.data[i];  // NOLINT
    if (cost < 0 || planner_common_param_.obstacle_threshold <= cost) {
      is_obstacle_table[i] = true;
    }
  }
  is_obstacle_table_ = is_obstacle_table;

  computeEDTMap();

  // construct collision indexes table
  if (is_collision_table_initialized == false) {
    for (int i = 0; i < planner_common_param_.theta_size; i++) {
      std::vector<IndexXY> indexes_2d, vertex_indexes_2d;
      computeCollisionIndexes(i, indexes_2d, vertex_indexes_2d);
      coll_indexes_table_.push_back(indexes_2d);
      vertex_indexes_table_.push_back(vertex_indexes_2d);
    }
    is_collision_table_initialized = true;
  }

  const double base2front = collision_vehicle_shape_.length - collision_vehicle_shape_.base2back;
  nb_of_margin_cells_ = std::ceil(
    std::hypot(0.5 * collision_vehicle_shape_.width, base2front) / costmap_.info.resolution);
}

void AbstractPlanningAlgorithm::computeEDTMap()
{
  edt_map_.clear();
  const int height = costmap_.info.height;
  const int width = costmap_.info.width;
  const double resolution_m = costmap_.info.resolution;
  std::vector<std::pair<double, geometry_msgs::msg::Point>> edt_map;
  edt_map.reserve(costmap_.data.size());

  std::vector<std::pair<double, geometry_msgs::msg::Point>> temporary_storage(width);
  // scan rows
  for (int i = 0; i < height; ++i) {
    double distance = resolution_m;
    bool found_obstacle = false;
    // forward scan
    for (int j = 0; j < width; ++j) {
      if (isObs(IndexXY{j, i})) {
        temporary_storage[j].first = 0.0;
        temporary_storage[j].second.x = 0.0;
        distance = resolution_m;
        found_obstacle = true;
      } else if (found_obstacle) {
        temporary_storage[j].first = distance;
        temporary_storage[j].second.x = -distance;
        distance += resolution_m;
      } else {
        temporary_storage[j].first = std::numeric_limits<double>::infinity();
      }
    }

    distance = resolution_m;
    found_obstacle = false;
    // backward scan
    for (int j = width - 1; j >= 0; --j) {
      if (isObs(IndexXY{j, i})) {
        distance = resolution_m;
        found_obstacle = true;
      } else if (found_obstacle && temporary_storage[j].first > distance) {
        temporary_storage[j].first = distance;
        temporary_storage[j].second.x = distance;
        distance += resolution_m;
      }
    }
    edt_map.insert(edt_map.end(), temporary_storage.begin(), temporary_storage.end());
  }

  temporary_storage.clear();
  temporary_storage.resize(height);
  // scan columns;
  for (int j = 0; j < width; ++j) {
    for (int i = 0; i < height; ++i) {
      int id = indexToId(IndexXY{j, i});
      double min_value = edt_map[id].first * edt_map[id].first;
      geometry_msgs::msg::Point rel_pos = edt_map[id].second;
      for (int k = 0; k < height; ++k) {
        id = indexToId(IndexXY{j, k});
        double dist = resolution_m * std::abs(static_cast<double>(i - k));
        double value = edt_map[id].first * edt_map[id].first + dist * dist;
        if (value < min_value) {
          min_value = value;
          rel_pos.x = edt_map[id].second.x;
          rel_pos.y = dist;
        }
      }
      temporary_storage[i].first = sqrt(min_value);
      temporary_storage[i].second = rel_pos;
    }
    for (int i = 0; i < height; ++i) {
      edt_map[indexToId(IndexXY{j, i})] = temporary_storage[i];
    }
  }
  for (const auto & edt : edt_map) {
    const double angle = std::atan2(edt.second.y, edt.second.x);
    edt_map_.push_back({edt.first, angle});
  }
}

inline bool isObs(const IndexType & index) const
{
  // NOTE: Accessing by .at() instead makes 1.2 times slower here.
  // Also, boundary check is already done in isOutOfRange before calling this function.
  // So, basically .at() is not necessary.
  return is_obstacle_table_[indexToId(index)];
}

inline int indexToId(const IndexType & index) const
{
  return index.y * costmap_.info.width + index.x;
}

inline int indexToId(const IndexType & index) const
{
  return index.y * costmap_.info.width + index.x;
}

void AbstractPlanningAlgorithm::computeCollisionIndexes(
  int theta_index, std::vector<IndexXY> & indexes_2d,
  std::vector<IndexXY> & vertex_indexes_2d) const
{
  IndexXYT base_index{0, 0, theta_index};
  const VehicleShape & vehicle_shape = collision_vehicle_shape_;

  // Define the robot as rectangle
  const double back = -1.0 * vehicle_shape.base2back;
  const double front = vehicle_shape.length - vehicle_shape.base2back;
  const double right = -1.0 * vehicle_shape.width / 2.0;
  const double left = vehicle_shape.width / 2.0;

  const auto base_pose = index2pose(costmap_, base_index, planner_common_param_.theta_size);
  const auto base_theta = tf2::getYaw(base_pose.orientation);

  // Convert each point to index and check if the node is Obstacle
  const auto addIndex2d = [&](
                            const double x, const double y, std::vector<IndexXY> & indexes_cache) {
    // Calculate offset in rotated frame
    const double offset_x = std::cos(base_theta) * x - std::sin(base_theta) * y;
    const double offset_y = std::sin(base_theta) * x + std::cos(base_theta) * y;

    geometry_msgs::msg::Pose pose_local;
    pose_local.position.x = base_pose.position.x + offset_x;
    pose_local.position.y = base_pose.position.y + offset_y;

    const auto index = pose2index(costmap_, pose_local, planner_common_param_.theta_size);
    const auto index_2d = IndexXY{index.x, index.y};
    indexes_cache.push_back(index_2d);
  };

  for (double x = back; x <= front; x += costmap_.info.resolution / 2) {
    for (double y = right; y <= left; y += costmap_.info.resolution / 2) {
      addIndex2d(x, y, indexes_2d);
    }
    addIndex2d(x, left, indexes_2d);
  }
  for (double y = right; y <= left; y += costmap_.info.resolution / 2) {
    addIndex2d(front, y, indexes_2d);
  }
  addIndex2d(front, left, indexes_2d);

  const auto compareIndex2d = [](const IndexXY & left, const IndexXY & right) {
    if (left.x != right.x) {
      return (left.x < right.x);
    } else {
      return (left.y < right.y);
    }
  };

  const auto equalIndex2d = [](const IndexXY & left, const IndexXY & right) {
    return ((left.x == right.x) && (left.y == right.y));
  };

  // remove duplicate indexes
  std::sort(indexes_2d.begin(), indexes_2d.end(), compareIndex2d);
  indexes_2d.erase(
    std::unique(indexes_2d.begin(), indexes_2d.end(), equalIndex2d), indexes_2d.end());

  addIndex2d(front, left, vertex_indexes_2d);
  addIndex2d(front, right, vertex_indexes_2d);
  addIndex2d(back, right, vertex_indexes_2d);
  addIndex2d(back, left, vertex_indexes_2d);
}

geometry_msgs::msg::Pose index2pose(
  const nav_msgs::msg::OccupancyGrid & costmap, const IndexXYT & index, const int theta_size)
{
  geometry_msgs::msg::Pose pose_local;

  pose_local.position.x = index.x * costmap.info.resolution;
  pose_local.position.y = index.y * costmap.info.resolution;

  const double angle_resolution = 2.0 * M_PI / theta_size;
  const double yaw = index.theta * angle_resolution;
  pose_local.orientation = create_quaternion_from_yaw(yaw);

  return pose_local;
}

using autoware_utils_geometry::create_quaternion_from_yaw;

geometry_msgs::msg::Pose transformPose(
  const geometry_msgs::msg::Pose & pose, const geometry_msgs::msg::TransformStamped & transform)
{
  geometry_msgs::msg::Pose transformed_pose;
  tf2::doTransform(pose, transformed_pose, transform);

  return transformed_pose;
}

IndexXYT pose2index(
  const nav_msgs::msg::OccupancyGrid & costmap, const geometry_msgs::msg::Pose & pose_local,
  const int theta_size)
{
  const int index_x = std::round(pose_local.position.x / costmap.info.resolution);
  const int index_y = std::round(pose_local.position.y / costmap.info.resolution);
  const int index_theta = discretizeAngle(tf2::getYaw(pose_local.orientation), theta_size);
  return {index_x, index_y, index_theta};
}

int discretizeAngle(const double theta, const int theta_size)
{
  const double angle_resolution = 2.0 * M_PI / theta_size;
  return static_cast<int>(std::round(normalize_radian(theta, 0.0) / angle_resolution)) % theta_size;
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

[[nodiscard]] size_t findNearestIndex(const T & points, const geometry_msgs::msg::Point & point)
{
  validateNonEmpty(points);

  double min_dist = std::numeric_limits<double>::max();
  size_t min_idx = 0;

  for (size_t i = 0; i < points.size(); ++i) {
    const auto dist = autoware_utils_geometry::calc_squared_distance2d(points.at(i), point);
    if (dist < min_dist) {
      min_dist = dist;
      min_idx = i;
    }
  }
  return min_idx;
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

Trajectory get_partial_trajectory(
  const Trajectory & trajectory, const size_t start_index, const size_t end_index,
  const rclcpp::Clock::SharedPtr clock)
{
  Trajectory partial_trajectory;
  partial_trajectory.header = trajectory.header;
  partial_trajectory.header.stamp = clock->now();

  partial_trajectory.points.reserve(trajectory.points.size());
  for (size_t i = start_index; i <= end_index; ++i) {
    partial_trajectory.points.push_back(trajectory.points.at(i));
  }

  // Modify velocity at start/end point
  if (partial_trajectory.points.size() >= 2) {
    partial_trajectory.points.front().longitudinal_velocity_mps =
      partial_trajectory.points.at(1).longitudinal_velocity_mps;
  }
  if (!partial_trajectory.points.empty()) {
    partial_trajectory.points.back().longitudinal_velocity_mps = 0;
  }

  return partial_trajectory;
}

bool AbstractPlanningAlgorithm::hasObstacleOnTrajectory(
  const geometry_msgs::msg::PoseArray & trajectory) const
{
  for (const auto & pose : trajectory.poses) {
    const auto pose_local = global2local(costmap_, pose);
    if (detectCollision(pose_local)) {
      return true;
    }
  }

  return false;
}

geometry_msgs::msg::Pose global2local(
  const nav_msgs::msg::OccupancyGrid & costmap, const geometry_msgs::msg::Pose & pose_global)
{
  tf2::Transform tf_origin;
  tf2::convert(costmap.info.origin, tf_origin);

  geometry_msgs::msg::TransformStamped transform;
  transform.transform = tf2::toMsg(tf_origin.inverse());

  return transformPose(pose_global, transform);
}

geometry_msgs::msg::Pose transformPose(
  const geometry_msgs::msg::Pose & pose, const geometry_msgs::msg::TransformStamped & transform)
{
  geometry_msgs::msg::Pose transformed_pose;
  tf2::doTransform(pose, transformed_pose, transform);

  return transformed_pose;
}

bool AbstractPlanningAlgorithm::detectCollision(const IndexXYT & base_index) const
{
  if (coll_indexes_table_.empty()) {
    std::cerr << "[abstract_algorithm] setMap has not yet been done." << std::endl;
    return false;
  }

  if (detectBoundaryExit(base_index)) return true;

  double obstacle_edt = getObstacleEDT(base_index).distance;

  // if nearest obstacle is further than largest dimension, no collision is guaranteed
  // if nearest obstacle is closer than smallest dimension, collision is guaranteed
  if (obstacle_edt > collision_vehicle_shape_.max_dimension) return false;
  if (obstacle_edt < collision_vehicle_shape_.min_dimension) return true;

  const auto & coll_indexes_2d = coll_indexes_table_[base_index.theta];
  for (const auto & coll_index_2d : coll_indexes_2d) {
    IndexXY coll_index{coll_index_2d.x, coll_index_2d.y};
    // must slide to current base position
    coll_index.x += base_index.x;
    coll_index.y += base_index.y;

    if (isObs(coll_index)) {
      return true;
    }
  }

  return false;
}

bool AbstractPlanningAlgorithm::detectBoundaryExit(const IndexXYT & base_index) const
{
  if (isWithinMargin(base_index)) return false;
  const auto & vertex_indexes_2d = vertex_indexes_table_[base_index.theta];
  for (const auto & vertex_index_2d : vertex_indexes_2d) {
    IndexXY vertex_index{vertex_index_2d.x, vertex_index_2d.y};
    // must slide to current base position
    vertex_index.x += base_index.x;
    vertex_index.y += base_index.y;
    if (isOutOfRange(vertex_index)) {
      return true;
    }
  }
  return false;
}

inline bool isWithinMargin(const IndexType & index) const
{
  if (
    index.x < nb_of_margin_cells_ ||
    static_cast<int>(costmap_.info.width) - index.x < nb_of_margin_cells_) {
    return false;
  }
  if (
    index.y < nb_of_margin_cells_ ||
    static_cast<int>(costmap_.info.height) - index.y < nb_of_margin_cells_) {
    return false;
  }
  return true;
}

inline bool isOutOfRange(const IndexType & index) const
{
  if (index.x < 0 || static_cast<int>(costmap_.info.width) <= index.x) {
    return true;
  }
  if (index.y < 0 || static_cast<int>(costmap_.info.height) <= index.y) {
    return true;
  }
  return false;
}

inline EDTData getObstacleEDT(const IndexType & index) const
{
  return edt_map_[indexToId(index)];
}

inline int indexToId(const IndexType & index) const
{
  return index.y * costmap_.info.width + index.x;
}

inline bool isObs(const IndexType & index) const
{
  // NOTE: Accessing by .at() instead makes 1.2 times slower here.
  // Also, boundary check is already done in isOutOfRange before calling this function.
  // So, basically .at() is not necessary.
  return is_obstacle_table_[indexToId(index)];
}

inline int indexToId(const IndexType & index) const
{
  return index.y * costmap_.info.width + index.x;
}

double calc_distance_2d(const Trajectory & trajectory, const Pose & pose)
{
  const auto idx = autoware::motion_utils::findNearestIndex(trajectory.points, pose.position);
  return autoware_utils::calc_distance2d(trajectory.points.at(idx), pose);
}

[[nodiscard]] size_t findNearestIndex(const T & points, const geometry_msgs::msg::Point & point)
{
  validateNonEmpty(points);

  double min_dist = std::numeric_limits<double>::max();
  size_t min_idx = 0;

  for (size_t i = 0; i < points.size(); ++i) {
    const auto dist = autoware_utils_geometry::calc_squared_distance2d(points.at(i), point);
    if (dist < min_dist) {
      min_dist = dist;
      min_idx = i;
    }
  }
  return min_idx;
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

void FreespacePlannerNode::planTrajectory()
{
  if (occupancy_grid_ == nullptr) {
    return;
  }

  // Provide robot shape and map for the planner
  algo_->setMap(*occupancy_grid_);

  // Calculate poses in costmap frame
  const auto current_pose_in_costmap_frame = utils::transform_pose(
    current_pose_.pose,
    getTransform(occupancy_grid_->header.frame_id, current_pose_.header.frame_id));

  const auto goal_pose_in_costmap_frame = utils::transform_pose(
    goal_pose_.pose, getTransform(occupancy_grid_->header.frame_id, goal_pose_.header.frame_id));

  // execute planning
  const rclcpp::Time start = get_clock()->now();
  std::string error_msg;
  bool result = false;
  try {
    result = algo_->makePlan(current_pose_in_costmap_frame, goal_pose_in_costmap_frame);
  } catch (const std::exception & e) {
    error_msg = e.what();
  }
  const rclcpp::Time end = get_clock()->now();

  RCLCPP_DEBUG(get_logger(), "Freespace planning: %f [s]", (end - start).seconds());

  if (result) {
    RCLCPP_DEBUG(get_logger(), "Found goal!");
    trajectory_ = utils::create_trajectory(
      current_pose_, algo_->getWaypoints(), node_param_.waypoints_velocity);
    reversing_indices_ = utils::get_reversing_indices(trajectory_);
    prev_target_index_ = 0;
    target_index_ = utils::get_next_target_index(
      trajectory_.points.size(), reversing_indices_, prev_target_index_);
  } else {
    RCLCPP_INFO(get_logger(), "Can't find goal: %s", error_msg.c_str());
    reset();
  }
}

void AbstractPlanningAlgorithm::setMap(const nav_msgs::msg::OccupancyGrid & costmap)
{
  costmap_ = costmap;

  const uint32_t nb_of_cells = costmap_.data.size();
  // Initialize status
  std::vector<bool> is_obstacle_table;
  is_obstacle_table.resize(nb_of_cells);
  for (uint32_t i = 0; i < nb_of_cells; ++i) {
    const int cost = costmap_.data[i];  // NOLINT
    if (cost < 0 || planner_common_param_.obstacle_threshold <= cost) {
      is_obstacle_table[i] = true;
    }
  }
  is_obstacle_table_ = is_obstacle_table;

  computeEDTMap();

  // construct collision indexes table
  if (is_collision_table_initialized == false) {
    for (int i = 0; i < planner_common_param_.theta_size; i++) {
      std::vector<IndexXY> indexes_2d, vertex_indexes_2d;
      computeCollisionIndexes(i, indexes_2d, vertex_indexes_2d);
      coll_indexes_table_.push_back(indexes_2d);
      vertex_indexes_table_.push_back(vertex_indexes_2d);
    }
    is_collision_table_initialized = true;
  }

  const double base2front = collision_vehicle_shape_.length - collision_vehicle_shape_.base2back;
  nb_of_margin_cells_ = std::ceil(
    std::hypot(0.5 * collision_vehicle_shape_.width, base2front) / costmap_.info.resolution);
}

void AbstractPlanningAlgorithm::computeEDTMap()
{
  edt_map_.clear();
  const int height = costmap_.info.height;
  const int width = costmap_.info.width;
  const double resolution_m = costmap_.info.resolution;
  std::vector<std::pair<double, geometry_msgs::msg::Point>> edt_map;
  edt_map.reserve(costmap_.data.size());

  std::vector<std::pair<double, geometry_msgs::msg::Point>> temporary_storage(width);
  // scan rows
  for (int i = 0; i < height; ++i) {
    double distance = resolution_m;
    bool found_obstacle = false;
    // forward scan
    for (int j = 0; j < width; ++j) {
      if (isObs(IndexXY{j, i})) {
        temporary_storage[j].first = 0.0;
        temporary_storage[j].second.x = 0.0;
        distance = resolution_m;
        found_obstacle = true;
      } else if (found_obstacle) {
        temporary_storage[j].first = distance;
        temporary_storage[j].second.x = -distance;
        distance += resolution_m;
      } else {
        temporary_storage[j].first = std::numeric_limits<double>::infinity();
      }
    }

    distance = resolution_m;
    found_obstacle = false;
    // backward scan
    for (int j = width - 1; j >= 0; --j) {
      if (isObs(IndexXY{j, i})) {
        distance = resolution_m;
        found_obstacle = true;
      } else if (found_obstacle && temporary_storage[j].first > distance) {
        temporary_storage[j].first = distance;
        temporary_storage[j].second.x = distance;
        distance += resolution_m;
      }
    }
    edt_map.insert(edt_map.end(), temporary_storage.begin(), temporary_storage.end());
  }

  temporary_storage.clear();
  temporary_storage.resize(height);
  // scan columns;
  for (int j = 0; j < width; ++j) {
    for (int i = 0; i < height; ++i) {
      int id = indexToId(IndexXY{j, i});
      double min_value = edt_map[id].first * edt_map[id].first;
      geometry_msgs::msg::Point rel_pos = edt_map[id].second;
      for (int k = 0; k < height; ++k) {
        id = indexToId(IndexXY{j, k});
        double dist = resolution_m * std::abs(static_cast<double>(i - k));
        double value = edt_map[id].first * edt_map[id].first + dist * dist;
        if (value < min_value) {
          min_value = value;
          rel_pos.x = edt_map[id].second.x;
          rel_pos.y = dist;
        }
      }
      temporary_storage[i].first = sqrt(min_value);
      temporary_storage[i].second = rel_pos;
    }
    for (int i = 0; i < height; ++i) {
      edt_map[indexToId(IndexXY{j, i})] = temporary_storage[i];
    }
  }
  for (const auto & edt : edt_map) {
    const double angle = std::atan2(edt.second.y, edt.second.x);
    edt_map_.push_back({edt.first, angle});
  }
}

inline bool isObs(const IndexType & index) const
{
  // NOTE: Accessing by .at() instead makes 1.2 times slower here.
  // Also, boundary check is already done in isOutOfRange before calling this function.
  // So, basically .at() is not necessary.
  return is_obstacle_table_[indexToId(index)];
}

inline int indexToId(const IndexType & index) const
{
  return index.y * costmap_.info.width + index.x;
}

inline int indexToId(const IndexType & index) const
{
  return index.y * costmap_.info.width + index.x;
}

void AbstractPlanningAlgorithm::computeCollisionIndexes(
  int theta_index, std::vector<IndexXY> & indexes_2d,
  std::vector<IndexXY> & vertex_indexes_2d) const
{
  IndexXYT base_index{0, 0, theta_index};
  const VehicleShape & vehicle_shape = collision_vehicle_shape_;

  // Define the robot as rectangle
  const double back = -1.0 * vehicle_shape.base2back;
  const double front = vehicle_shape.length - vehicle_shape.base2back;
  const double right = -1.0 * vehicle_shape.width / 2.0;
  const double left = vehicle_shape.width / 2.0;

  const auto base_pose = index2pose(costmap_, base_index, planner_common_param_.theta_size);
  const auto base_theta = tf2::getYaw(base_pose.orientation);

  // Convert each point to index and check if the node is Obstacle
  const auto addIndex2d = [&](
                            const double x, const double y, std::vector<IndexXY> & indexes_cache) {
    // Calculate offset in rotated frame
    const double offset_x = std::cos(base_theta) * x - std::sin(base_theta) * y;
    const double offset_y = std::sin(base_theta) * x + std::cos(base_theta) * y;

    geometry_msgs::msg::Pose pose_local;
    pose_local.position.x = base_pose.position.x + offset_x;
    pose_local.position.y = base_pose.position.y + offset_y;

    const auto index = pose2index(costmap_, pose_local, planner_common_param_.theta_size);
    const auto index_2d = IndexXY{index.x, index.y};
    indexes_cache.push_back(index_2d);
  };

  for (double x = back; x <= front; x += costmap_.info.resolution / 2) {
    for (double y = right; y <= left; y += costmap_.info.resolution / 2) {
      addIndex2d(x, y, indexes_2d);
    }
    addIndex2d(x, left, indexes_2d);
  }
  for (double y = right; y <= left; y += costmap_.info.resolution / 2) {
    addIndex2d(front, y, indexes_2d);
  }
  addIndex2d(front, left, indexes_2d);

  const auto compareIndex2d = [](const IndexXY & left, const IndexXY & right) {
    if (left.x != right.x) {
      return (left.x < right.x);
    } else {
      return (left.y < right.y);
    }
  };

  const auto equalIndex2d = [](const IndexXY & left, const IndexXY & right) {
    return ((left.x == right.x) && (left.y == right.y));
  };

  // remove duplicate indexes
  std::sort(indexes_2d.begin(), indexes_2d.end(), compareIndex2d);
  indexes_2d.erase(
    std::unique(indexes_2d.begin(), indexes_2d.end(), equalIndex2d), indexes_2d.end());

  addIndex2d(front, left, vertex_indexes_2d);
  addIndex2d(front, right, vertex_indexes_2d);
  addIndex2d(back, right, vertex_indexes_2d);
  addIndex2d(back, left, vertex_indexes_2d);
}

geometry_msgs::msg::Pose index2pose(
  const nav_msgs::msg::OccupancyGrid & costmap, const IndexXYT & index, const int theta_size)
{
  geometry_msgs::msg::Pose pose_local;

  pose_local.position.x = index.x * costmap.info.resolution;
  pose_local.position.y = index.y * costmap.info.resolution;

  const double angle_resolution = 2.0 * M_PI / theta_size;
  const double yaw = index.theta * angle_resolution;
  pose_local.orientation = create_quaternion_from_yaw(yaw);

  return pose_local;
}

using autoware_utils_geometry::create_quaternion_from_yaw;

geometry_msgs::msg::Pose transformPose(
  const geometry_msgs::msg::Pose & pose, const geometry_msgs::msg::TransformStamped & transform)
{
  geometry_msgs::msg::Pose transformed_pose;
  tf2::doTransform(pose, transformed_pose, transform);

  return transformed_pose;
}

IndexXYT pose2index(
  const nav_msgs::msg::OccupancyGrid & costmap, const geometry_msgs::msg::Pose & pose_local,
  const int theta_size)
{
  const int index_x = std::round(pose_local.position.x / costmap.info.resolution);
  const int index_y = std::round(pose_local.position.y / costmap.info.resolution);
  const int index_theta = discretizeAngle(tf2::getYaw(pose_local.orientation), theta_size);
  return {index_x, index_y, index_theta};
}

int discretizeAngle(const double theta, const int theta_size)
{
  const double angle_resolution = 2.0 * M_PI / theta_size;
  return static_cast<int>(std::round(normalize_radian(theta, 0.0) / angle_resolution)) % theta_size;
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

Pose transform_pose(const Pose & pose, const TransformStamped & transform)
{
  PoseStamped transformed_pose;
  PoseStamped orig_pose;
  orig_pose.pose = pose;
  tf2::doTransform(orig_pose, transformed_pose, transform);

  return transformed_pose.pose;
}

bool AstarSearch::makePlan(const Pose & start_pose, const Pose & goal_pose)
{
  resetData();

  start_pose_ = global2local(costmap_, start_pose);
  goal_pose_ = global2local(costmap_, goal_pose);

  if (detectCollision(start_pose_) || detectCollision(goal_pose_)) {
    throw std::logic_error("Invalid start or goal pose");
  }

  if (is_backward_search_) std::swap(start_pose_, goal_pose_);

  setCollisionFreeDistanceMap();

  is_multiple_goals_ = false;

  setStartNode();

  if (!search()) {
    throw std::logic_error("HA* failed to find path to goal");
  }

  return true;
}

void AstarSearch::resetData()
{
  // clearing openlist is necessary because otherwise remaining elements of openlist
  // point to deleted node.
  openlist_ = std::priority_queue<AstarNode *, std::vector<AstarNode *>, NodeComparison>();
  const int nb_of_grid_nodes = costmap_.info.width * costmap_.info.height;
  const int total_astar_node_count = nb_of_grid_nodes * planner_common_param_.theta_size;
  graph_.assign(total_astar_node_count, AstarNode{});
  col_free_distance_map_.assign(nb_of_grid_nodes, std::numeric_limits<double>::max());
  shifted_goal_pose_ = {};
}

geometry_msgs::msg::Pose global2local(
  const nav_msgs::msg::OccupancyGrid & costmap, const geometry_msgs::msg::Pose & pose_global)
{
  tf2::Transform tf_origin;
  tf2::convert(costmap.info.origin, tf_origin);

  geometry_msgs::msg::TransformStamped transform;
  transform.transform = tf2::toMsg(tf_origin.inverse());

  return transformPose(pose_global, transform);
}

geometry_msgs::msg::Pose transformPose(
  const geometry_msgs::msg::Pose & pose, const geometry_msgs::msg::TransformStamped & transform)
{
  geometry_msgs::msg::Pose transformed_pose;
  tf2::doTransform(pose, transformed_pose, transform);

  return transformed_pose;
}

bool AbstractPlanningAlgorithm::detectCollision(const geometry_msgs::msg::Pose & base_pose) const
{
  const auto base_index = pose2index(costmap_, base_pose, planner_common_param_.theta_size);
  return detectCollision(base_index);
}

IndexXYT pose2index(
  const nav_msgs::msg::OccupancyGrid & costmap, const geometry_msgs::msg::Pose & pose_local,
  const int theta_size)
{
  const int index_x = std::round(pose_local.position.x / costmap.info.resolution);
  const int index_y = std::round(pose_local.position.y / costmap.info.resolution);
  const int index_theta = discretizeAngle(tf2::getYaw(pose_local.orientation), theta_size);
  return {index_x, index_y, index_theta};
}

int discretizeAngle(const double theta, const int theta_size)
{
  const double angle_resolution = 2.0 * M_PI / theta_size;
  return static_cast<int>(std::round(normalize_radian(theta, 0.0) / angle_resolution)) % theta_size;
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

bool AbstractPlanningAlgorithm::detectCollision(const IndexXYT & base_index) const
{
  if (coll_indexes_table_.empty()) {
    std::cerr << "[abstract_algorithm] setMap has not yet been done." << std::endl;
    return false;
  }

  if (detectBoundaryExit(base_index)) return true;

  double obstacle_edt = getObstacleEDT(base_index).distance;

  // if nearest obstacle is further than largest dimension, no collision is guaranteed
  // if nearest obstacle is closer than smallest dimension, collision is guaranteed
  if (obstacle_edt > collision_vehicle_shape_.max_dimension) return false;
  if (obstacle_edt < collision_vehicle_shape_.min_dimension) return true;

  const auto & coll_indexes_2d = coll_indexes_table_[base_index.theta];
  for (const auto & coll_index_2d : coll_indexes_2d) {
    IndexXY coll_index{coll_index_2d.x, coll_index_2d.y};
    // must slide to current base position
    coll_index.x += base_index.x;
    coll_index.y += base_index.y;

    if (isObs(coll_index)) {
      return true;
    }
  }

  return false;
}

bool AbstractPlanningAlgorithm::detectBoundaryExit(const IndexXYT & base_index) const
{
  if (isWithinMargin(base_index)) return false;
  const auto & vertex_indexes_2d = vertex_indexes_table_[base_index.theta];
  for (const auto & vertex_index_2d : vertex_indexes_2d) {
    IndexXY vertex_index{vertex_index_2d.x, vertex_index_2d.y};
    // must slide to current base position
    vertex_index.x += base_index.x;
    vertex_index.y += base_index.y;
    if (isOutOfRange(vertex_index)) {
      return true;
    }
  }
  return false;
}

inline bool isWithinMargin(const IndexType & index) const
{
  if (
    index.x < nb_of_margin_cells_ ||
    static_cast<int>(costmap_.info.width) - index.x < nb_of_margin_cells_) {
    return false;
  }
  if (
    index.y < nb_of_margin_cells_ ||
    static_cast<int>(costmap_.info.height) - index.y < nb_of_margin_cells_) {
    return false;
  }
  return true;
}

inline bool isOutOfRange(const IndexType & index) const
{
  if (index.x < 0 || static_cast<int>(costmap_.info.width) <= index.x) {
    return true;
  }
  if (index.y < 0 || static_cast<int>(costmap_.info.height) <= index.y) {
    return true;
  }
  return false;
}

inline EDTData getObstacleEDT(const IndexType & index) const
{
  return edt_map_[indexToId(index)];
}

inline int indexToId(const IndexType & index) const
{
  return index.y * costmap_.info.width + index.x;
}

inline bool isObs(const IndexType & index) const
{
  // NOTE: Accessing by .at() instead makes 1.2 times slower here.
  // Also, boundary check is already done in isOutOfRange before calling this function.
  // So, basically .at() is not necessary.
  return is_obstacle_table_[indexToId(index)];
}

inline int indexToId(const IndexType & index) const
{
  return index.y * costmap_.info.width + index.x;
}

void AstarSearch::setCollisionFreeDistanceMap()
{
  using Entry = std::pair<IndexXY, double>;
  struct CompareEntry
  {
    bool operator()(const Entry & a, const Entry & b) const { return a.second > b.second; }
  };
  std::priority_queue<Entry, std::vector<Entry>, CompareEntry> heap;
  std::vector<bool> closed(col_free_distance_map_.size(), false);
  auto goal_index = pose2index(costmap_, goal_pose_, planner_common_param_.theta_size);
  col_free_distance_map_[indexToId(goal_index)] = 0.0;
  heap.push({IndexXY{goal_index.x, goal_index.y}, 0.0});

  Entry current;
  std::array<int, 3> offsets = {1, 0, -1};
  while (!heap.empty()) {
    current = heap.top();
    heap.pop();
    const int id = indexToId(current.first);
    if (closed[id]) continue;
    closed[id] = true;

    const auto & index = current.first;
    for (const auto & offset_x : offsets) {
      const int x = index.x + offset_x;
      for (const auto & offset_y : offsets) {
        const int y = index.y + offset_y;
        const IndexXY n_index{x, y};
        const double offset = std::abs(offset_x) + std::abs(offset_y);
        if (isOutOfRange(n_index) || isObs(n_index) || offset < 1) continue;
        if (getObstacleEDT(n_index).distance < 0.5 * collision_vehicle_shape_.width) continue;
        const int n_id = indexToId(n_index);
        const double dist = current.second + (sqrt(offset) * costmap_.info.resolution);
        if (closed[n_id] || col_free_distance_map_[n_id] < dist) continue;
        col_free_distance_map_[n_id] = dist;
        heap.push({n_index, dist});
      }
    }
  }
}

IndexXYT pose2index(
  const nav_msgs::msg::OccupancyGrid & costmap, const geometry_msgs::msg::Pose & pose_local,
  const int theta_size)
{
  const int index_x = std::round(pose_local.position.x / costmap.info.resolution);
  const int index_y = std::round(pose_local.position.y / costmap.info.resolution);
  const int index_theta = discretizeAngle(tf2::getYaw(pose_local.orientation), theta_size);
  return {index_x, index_y, index_theta};
}

int discretizeAngle(const double theta, const int theta_size)
{
  const double angle_resolution = 2.0 * M_PI / theta_size;
  return static_cast<int>(std::round(normalize_radian(theta, 0.0) / angle_resolution)) % theta_size;
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

inline bool isOutOfRange(const IndexType & index) const
{
  if (index.x < 0 || static_cast<int>(costmap_.info.width) <= index.x) {
    return true;
  }
  if (index.y < 0 || static_cast<int>(costmap_.info.height) <= index.y) {
    return true;
  }
  return false;
}

inline bool isObs(const IndexType & index) const
{
  // NOTE: Accessing by .at() instead makes 1.2 times slower here.
  // Also, boundary check is already done in isOutOfRange before calling this function.
  // So, basically .at() is not necessary.
  return is_obstacle_table_[indexToId(index)];
}

inline int indexToId(const IndexType & index) const
{
  return index.y * costmap_.info.width + index.x;
}

inline EDTData getObstacleEDT(const IndexType & index) const
{
  return edt_map_[indexToId(index)];
