bool AstarSearch::search()
{
  const rclcpp::Time begin = rclcpp::Clock(RCL_ROS_TIME).now();

  // Start A* search
  while (!openlist_.empty()) {
    // Check time and terminate if the search reaches the time limit
    const rclcpp::Time now = rclcpp::Clock(RCL_ROS_TIME).now();
    const double msec = (now - begin).seconds() * 1000.0;
    if (msec > planner_common_param_.time_limit) {
      return false;
    }

    // Expand minimum cost node
    AstarNode * current_node = openlist_.top();
    openlist_.pop();
    if (current_node->status == NodeStatus::Closed) continue;
    current_node->status = NodeStatus::Closed;

    if (isGoal(*current_node)) {
      goal_node_ = current_node;
      setPath(*current_node);
      return true;
    }

    expandNodes(*current_node);
    if (astar_param_.use_back) expandNodes(*current_node, true);
  }

  // Failed to find path
  return false;
}

bool AstarSearch::isGoal(const AstarNode & node) const
{
  const double lateral_goal_range = planner_common_param_.lateral_goal_range / 2.0;
  const double longitudinal_goal_range = planner_common_param_.longitudinal_goal_range / 2.0;
  const double goal_angle =
    autoware_utils_math::deg2rad(planner_common_param_.angle_goal_range / 2.0);

  const auto node_pose = node2pose(node);

  auto checkGoal = [this, &node_pose, &lateral_goal_range, &longitudinal_goal_range, &goal_angle,
                    &is_back = node.is_back](const Pose & pose) {
    const auto node_index = pose2index(costmap_, node_pose, planner_common_param_.theta_size);
    const auto goal_index = pose2index(costmap_, pose, planner_common_param_.theta_size);

    if (node_index == goal_index) return true;

    const auto relative_pose = calcRelativePose(pose, node_pose);

    bool is_behind_goal = relative_pose.position.x <= 0.0;

    if (astar_param_.only_behind_solutions && !is_behind_goal) {
      return false;
    }

    if (
      std::fabs(relative_pose.position.x) > longitudinal_goal_range ||
      std::fabs(relative_pose.position.y) > lateral_goal_range) {
      return false;
    }

    const auto angle_diff =
      autoware_utils_math::normalize_radian(tf2::getYaw(relative_pose.orientation));
    if (std::abs(angle_diff) > goal_angle) {
      return false;
    }

    const bool is_set_shifted_goal_pose =
      is_backward_search_ ? is_behind_goal == is_back : is_behind_goal != is_back;
    if (is_set_shifted_goal_pose) {
      setShiftedGoalPose(pose, relative_pose.position.y);
    }

    return true;
  };

  if (checkGoal(goal_pose_)) return true;

  return std::any_of(
    alternate_goals_.begin(), alternate_goals_.end(),
    [&checkGoal](const Pose & pose) { return checkGoal(pose); });
}

Pose AstarSearch::node2pose(const AstarNode & node) const
{
  Pose pose_local;

  pose_local.position.x = node.x;
  pose_local.position.y = node.y;
  pose_local.position.z = goal_pose_.position.z;
  pose_local.orientation = autoware_utils_geometry::create_quaternion_from_yaw(node.theta);

  return pose_local;
}

IndexXYT pose2index(
  const nav_msgs::msg::OccupancyGrid & costmap, const geometry_msgs::msg::Pose & pose_local,
  const int theta_size)
{
  const int index_x = std::round(pose_local.position.x / costmap.info.resolution);
  const int index_y = std::round(pose_local.position.y / costmap.info.resolution);
  const int index_theta = discretizeAngle(tf2::getYaw(pose_local.orientation), theta_size);
  return {index_x, index_y, index_theta};
}

int discretizeAngle(const double theta, const int theta_size)
{
  const double angle_resolution = 2.0 * M_PI / theta_size;
  return static_cast<int>(std::round(normalize_radian(theta, 0.0) / angle_resolution)) % theta_size;
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

Pose calcRelativePose(const Pose & base_pose, const Pose & pose)
{
  tf2::Transform tf_transform;
  tf2::convert(base_pose, tf_transform);

  geometry_msgs::msg::TransformStamped transform;
  transform.transform = tf2::toMsg(tf_transform.inverse());

  geometry_msgs::msg::PoseStamped transformed;
  geometry_msgs::msg::PoseStamped pose_orig;
  pose_orig.pose = pose;
  tf2::doTransform(pose_orig, transformed, transform);

  return transformed.pose;
}

void AstarSearch::setShiftedGoalPose(const Pose & goal_pose, const double lat_offset) const
{
  tf2::Transform tf;
  tf2::convert(goal_pose, tf);

  geometry_msgs::msg::TransformStamped transform;
  transform.transform = tf2::toMsg(tf);

  Pose lat_pose;
  lat_pose.position = geometry_msgs::build<geometry_msgs::msg::Point>().x(0.0).y(lat_offset).z(0.0);
  lat_pose.orientation =
    geometry_msgs::build<geometry_msgs::msg::Quaternion>().x(0.0).y(0.0).z(0.0).w(1.0);

  shifted_goal_pose_ = transformPose(lat_pose, transform);
}

geometry_msgs::msg::Pose transformPose(
  const geometry_msgs::msg::Pose & pose, const geometry_msgs::msg::TransformStamped & transform)
{
  geometry_msgs::msg::Pose transformed_pose;
  tf2::doTransform(pose, transformed_pose, transform);

  return transformed_pose;
}

void AstarSearch::expandNodes(AstarNode & current_node, const bool is_back)
{
  const auto current_pose = node2pose(current_node);
  const double direction = (is_back == is_backward_search_) ? 1.0 : -1.0;
  const double distance = getExpansionDistance(current_node) * direction;
  int steering_index = -1 * planner_common_param_.turning_steps;
  for (; steering_index <= planner_common_param_.turning_steps; ++steering_index) {
    // skip expansion back to parent
    if (
      current_node.parent != nullptr && is_back != current_node.is_back &&
      steering_index == current_node.steering_index) {
      continue;
    }

    const double steering = static_cast<double>(steering_index) * steering_resolution_;
    const auto next_pose = kinematic_bicycle_model::getPose(
      current_pose, collision_vehicle_shape_.base_length, steering, distance);
    const auto next_index = pose2index(costmap_, next_pose, planner_common_param_.theta_size);

    if (isOutOfRange(next_index) || isObs(next_index)) continue;

    AstarNode * next_node = &graph_[getKey(next_index)];
    if (next_node->status == NodeStatus::Closed || detectCollision(next_index)) continue;

    // Check intermediate points along the arc for collision
    const double abs_distance = std::abs(distance);
    if (astar_param_.adapt_expansion_distance && abs_distance > min_expansion_dist_) {
      const int n = static_cast<int>(abs_distance / min_expansion_dist_);
      bool has_intermediate_collision = false;
      for (int j = 1; j < n; ++j) {
        const double intermediate_dist = (abs_distance * j / n) * direction;
        const auto intermediate_pose = kinematic_bicycle_model::getPose(
          current_pose, collision_vehicle_shape_.base_length, steering, intermediate_dist);
        if (detectCollision(intermediate_pose)) {
          has_intermediate_collision = true;
          break;
        }
      }
      if (has_intermediate_collision) continue;
    }

    const auto obs_edt = getObstacleEDT(next_index);
    const bool is_direction_switch =
      (current_node.parent != nullptr) && (is_back != current_node.is_back);

    double total_weight = 1.0;
    total_weight += getSteeringCost(steering_index);
    if (is_back) total_weight *= (1.0 + planner_common_param_.reverse_weight);

    double move_cost = current_node.gc + (total_weight * std::abs(distance));
    move_cost += getSteeringChangeCost(steering_index, current_node.steering_index);
    move_cost += getObsDistanceCost(next_index, obs_edt);
    move_cost += getLatDistanceCost(next_pose);
    if (is_direction_switch) move_cost += getDirectionChangeCost(current_node.dir_distance);

    double total_cost = move_cost + estimateCost(next_pose, next_index);
    // Compare cost
    if (next_node->status == NodeStatus::None || next_node->fc > total_cost) {
      next_node->status = NodeStatus::Open;
      next_node->set(next_pose, move_cost, total_cost, steering_index, is_back);
      next_node->dir_distance =
        std::abs(distance) + (is_direction_switch ? 0.0 : current_node.dir_distance);
      next_node->dist_to_goal = calc_distance2d(next_pose, goal_pose_);
      next_node->dist_to_obs = obs_edt.distance;
      next_node->parent = &current_node;
      openlist_.push(next_node);
      continue;
    }
  }
}

Pose AstarSearch::node2pose(const AstarNode & node) const
{
  Pose pose_local;

  pose_local.position.x = node.x;
  pose_local.position.y = node.y;
  pose_local.position.z = goal_pose_.position.z;
  pose_local.orientation = autoware_utils_geometry::create_quaternion_from_yaw(node.theta);

  return pose_local;
}

geometry_msgs::msg::Quaternion create_quaternion_from_yaw(const double yaw)
{
  tf2::Quaternion q;
  q.setRPY(0, 0, yaw);
  return tf2::toMsg(q);
}

double AstarSearch::getExpansionDistance(const AstarNode & current_node) const
{
  if (!astar_param_.adapt_expansion_distance || max_expansion_dist_ <= min_expansion_dist_) {
    return min_expansion_dist_;
  }
  double exp_dist = std::min(
    current_node.dist_to_goal * dist_to_goal_expansion_factor_,
    current_node.dist_to_obs * dist_to_obs_expansion_factor_);
  return std::clamp(exp_dist, min_expansion_dist_, max_expansion_dist_);
}

inline geometry_msgs::msg::Pose getPose(
  const geometry_msgs::msg::Pose & current_pose, const double base_length,
  const double steering_angle, const double distance)
{
  auto pose = current_pose;
  const double yaw = tf2::getYaw(current_pose.orientation);
  if (std::abs(steering_angle) < eps) {
    pose.position.x += distance * std::cos(yaw);
    pose.position.y += distance * std::sin(yaw);
    return pose;
  }

  const double R = getTurningRadius(base_length, steering_angle);
  const double beta = distance / R;
  pose.position.x += (R * std::sin(yaw + beta) - R * std::sin(yaw));
  pose.position.y += (R * std::cos(yaw) - R * std::cos(yaw + beta));
  pose.orientation = autoware_utils_geometry::create_quaternion_from_yaw(yaw + beta);
  return pose;
}

inline double getTurningRadius(const double base_length, const double steering_angle)
{
  return base_length / std::tan(steering_angle);
}

geometry_msgs::msg::Quaternion create_quaternion_from_yaw(const double yaw)
{
  tf2::Quaternion q;
  q.setRPY(0, 0, yaw);
  return tf2::toMsg(q);
}

bool AbstractPlanningAlgorithm::detectCollision(const geometry_msgs::msg::Pose & base_pose) const
{
  const auto base_index = pose2index(costmap_, base_pose, planner_common_param_.theta_size);
  return detectCollision(base_index);
}

IndexXYT pose2index(
  const nav_msgs::msg::OccupancyGrid & costmap, const geometry_msgs::msg::Pose & pose_local,
  const int theta_size)
{
  const int index_x = std::round(pose_local.position.x / costmap.info.resolution);
  const int index_y = std::round(pose_local.position.y / costmap.info.resolution);
  const int index_theta = discretizeAngle(tf2::getYaw(pose_local.orientation), theta_size);
  return {index_x, index_y, index_theta};
}

int discretizeAngle(const double theta, const int theta_size)
{
  const double angle_resolution = 2.0 * M_PI / theta_size;
  return static_cast<int>(std::round(normalize_radian(theta, 0.0) / angle_resolution)) % theta_size;
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

bool AbstractPlanningAlgorithm::detectCollision(const IndexXYT & base_index) const
{
  if (coll_indexes_table_.empty()) {
    std::cerr << "[abstract_algorithm] setMap has not yet been done." << std::endl;
    return false;
  }

  if (detectBoundaryExit(base_index)) return true;

  double obstacle_edt = getObstacleEDT(base_index).distance;

  // if nearest obstacle is further than largest dimension, no collision is guaranteed
  // if nearest obstacle is closer than smallest dimension, collision is guaranteed
  if (obstacle_edt > collision_vehicle_shape_.max_dimension) return false;
  if (obstacle_edt < collision_vehicle_shape_.min_dimension) return true;

  const auto & coll_indexes_2d = coll_indexes_table_[base_index.theta];
  for (const auto & coll_index_2d : coll_indexes_2d) {
    IndexXY coll_index{coll_index_2d.x, coll_index_2d.y};
    // must slide to current base position
    coll_index.x += base_index.x;
    coll_index.y += base_index.y;

    if (isObs(coll_index)) {
      return true;
    }
  }

  return false;
}

bool AbstractPlanningAlgorithm::detectBoundaryExit(const IndexXYT & base_index) const
{
  if (isWithinMargin(base_index)) return false;
  const auto & vertex_indexes_2d = vertex_indexes_table_[base_index.theta];
  for (const auto & vertex_index_2d : vertex_indexes_2d) {
    IndexXY vertex_index{vertex_index_2d.x, vertex_index_2d.y};
    // must slide to current base position
    vertex_index.x += base_index.x;
    vertex_index.y += base_index.y;
    if (isOutOfRange(vertex_index)) {
      return true;
    }
  }
  return false;
}

inline bool isWithinMargin(const IndexType & index) const
{
  if (
    index.x < nb_of_margin_cells_ ||
    static_cast<int>(costmap_.info.width) - index.x < nb_of_margin_cells_) {
    return false;
  }
  if (
    index.y < nb_of_margin_cells_ ||
    static_cast<int>(costmap_.info.height) - index.y < nb_of_margin_cells_) {
    return false;
  }
  return true;
}

inline bool isOutOfRange(const IndexType & index) const
{
  if (index.x < 0 || static_cast<int>(costmap_.info.width) <= index.x) {
    return true;
  }
  if (index.y < 0 || static_cast<int>(costmap_.info.height) <= index.y) {
    return true;
  }
  return false;
}

inline EDTData getObstacleEDT(const IndexType & index) const
{
  return edt_map_[indexToId(index)];
}

inline int indexToId(const IndexType & index) const
{
  return index.y * costmap_.info.width + index.x;
}

inline bool isObs(const IndexType & index) const
{
  // NOTE: Accessing by .at() instead makes 1.2 times slower here.
  // Also, boundary check is already done in isOutOfRange before calling this function.
  // So, basically .at() is not necessary.
  return is_obstacle_table_[indexToId(index)];
}

inline int indexToId(const IndexType & index) const
{
  return index.y * costmap_.info.width + index.x;
}

double AstarSearch::estimateCost(const Pose & pose, const IndexXYT & index) const
{
  double total_cost = col_free_distance_map_[indexToId(index)];
  // Temporarily, until reeds_shepp gets stable.
  if (use_reeds_shepp_) {
    total_cost =
      std::max(total_cost, calcReedsSheppDistance(pose, goal_pose_, avg_turning_radius_));
  }
  return astar_param_.distance_heuristic_weight * total_cost;
}

inline int indexToId(const IndexType & index) const
{
  return index.y * costmap_.info.width + index.x;
}

double calcReedsSheppDistance(const Pose & p1, const Pose & p2, double radius)
{
  const auto rs_space = ReedsSheppStateSpace(radius);
  const ReedsSheppStateSpace::StateXYT pose0{
    p1.position.x, p1.position.y, tf2::getYaw(p1.orientation)};
  const ReedsSheppStateSpace::StateXYT pose1{
    p2.position.x, p2.position.y, tf2::getYaw(p2.orientation)};
  return rs_space.distance(pose0, pose1);
}

double ReedsSheppStateSpace::distance(const StateXYT & s0, const StateXYT & s1) const
{
  return rho_ * reedsShepp(s0, s1).length();
}

ReedsSheppStateSpace::ReedsSheppPath reedsShepp(double x, double y, double phi)
{
  ReedsSheppStateSpace::ReedsSheppPath path;
  CSC(x, y, phi, path);
  CCC(x, y, phi, path);
  CCCC(x, y, phi, path);
  CCSC(x, y, phi, path);
  CCSCC(x, y, phi, path);
  return path;
}

void CSC(double x, double y, double phi, ReedsSheppStateSpace::ReedsSheppPath & path)
{
  double t, u, v, L_min = path.length(), L;
  if (LpSpLp(x, y, phi, t, u, v) && L_min > (L = std::abs(t) + std::abs(u) + std::abs(v))) {
    path =
      ReedsSheppStateSpace::ReedsSheppPath(ReedsSheppStateSpace::reedsSheppPathType[14], t, u, v);
    L_min = L;
  }
  if (
    LpSpLp(-x, y, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // time flip
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[14], -t, -u, -v);
    L_min = L;
  }
  if (
    LpSpLp(x, -y, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // reflect
  {
    path =
      ReedsSheppStateSpace::ReedsSheppPath(ReedsSheppStateSpace::reedsSheppPathType[15], t, u, v);
    L_min = L;
  }
  if (
    LpSpLp(-x, -y, phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // time flip + reflect
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[15], -t, -u, -v);
    L_min = L;
  }
  if (LpSpRp(x, y, phi, t, u, v) && L_min > (L = std::abs(t) + std::abs(u) + std::abs(v))) {
    path =
      ReedsSheppStateSpace::ReedsSheppPath(ReedsSheppStateSpace::reedsSheppPathType[12], t, u, v);
    L_min = L;
  }
  if (
    LpSpRp(-x, y, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // time flip
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[12], -t, -u, -v);
    L_min = L;
  }
  if (
    LpSpRp(x, -y, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // reflect
  {
    path =
      ReedsSheppStateSpace::ReedsSheppPath(ReedsSheppStateSpace::reedsSheppPathType[13], t, u, v);
    L_min = L;
  }
  // time flip + reflect
  if (LpSpRp(-x, -y, phi, t, u, v) && L_min > (std::abs(t) + std::abs(u) + std::abs(v))) {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[13], -t, -u, -v);
  }
}

inline bool LpSpLp(double x, double y, double phi, double & t, double & u, double & v)
{
  polar(x - std::sin(phi), y - 1. + std::cos(phi), u, t);
  if (t >= -ZERO) {
    v = mod2pi(phi - t);
    if (v >= -ZERO) {
      assert(std::abs(u * std::cos(t) + std::sin(phi) - x) < RS_EPS);
      assert(std::abs(u * std::sin(t) - std::cos(phi) + 1 - y) < RS_EPS);
      assert(std::abs(mod2pi(t + v - phi)) < RS_EPS);
      return true;
    }
  }
  return false;
}

inline void polar(double x, double y, double & r, double & theta)
{
  r = std::sqrt(x * x + y * y);
  theta = std::atan2(y, x);
}

inline double mod2pi(double x)
{
  double v = std::fmod(x, twopi);
  if (v < -pi) {
    v += twopi;
  } else if (v > pi) {
    v -= twopi;
  }
  return v;
}

inline bool LpSpRp(double x, double y, double phi, double & t, double & u, double & v)
{
  double t1, u1;
  polar(x + std::sin(phi), y - 1. - std::cos(phi), u1, t1);
  u1 = u1 * u1;
  if (u1 >= 4.) {
    double theta;
    u = sqrt(u1 - 4.);
    theta = std::atan2(2., u);
    t = mod2pi(t1 + theta);
    v = mod2pi(t - phi);
    assert(std::abs(2 * std::sin(t) + u * std::cos(t) - std::sin(phi) - x) < RS_EPS);
    assert(std::abs(-2 * std::cos(t) + u * std::sin(t) + std::cos(phi) + 1 - y) < RS_EPS);
    assert(std::abs(mod2pi(t - v - phi)) < RS_EPS);
    return t >= -ZERO && v >= -ZERO;
  }
  return false;
}

inline void polar(double x, double y, double & r, double & theta)
{
  r = std::sqrt(x * x + y * y);
  theta = std::atan2(y, x);
}

inline double mod2pi(double x)
{
  double v = std::fmod(x, twopi);
  if (v < -pi) {
    v += twopi;
  } else if (v > pi) {
    v -= twopi;
  }
  return v;
}

void CCC(double x, double y, double phi, ReedsSheppStateSpace::ReedsSheppPath & path)
{
  double t, u, v, L_min = path.length(), L;
  if (LpRmL(x, y, phi, t, u, v) && L_min > (L = std::abs(t) + std::abs(u) + std::abs(v))) {
    path =
      ReedsSheppStateSpace::ReedsSheppPath(ReedsSheppStateSpace::reedsSheppPathType[0], t, u, v);
    L_min = L;
  }
  if (LpRmL(-x, y, -phi, t, u, v) && L_min > (L = std::abs(t) + std::abs(u) + std::abs(v))) {
    // time flip
    path =
      ReedsSheppStateSpace::ReedsSheppPath(ReedsSheppStateSpace::reedsSheppPathType[0], -t, -u, -v);
    L_min = L;
  }
  if (
    LpRmL(x, -y, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // reflect
  {
    path =
      ReedsSheppStateSpace::ReedsSheppPath(ReedsSheppStateSpace::reedsSheppPathType[1], t, u, v);
    L_min = L;
  }
  if (
    LpRmL(-x, -y, phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // time flip + reflect
  {
    path =
      ReedsSheppStateSpace::ReedsSheppPath(ReedsSheppStateSpace::reedsSheppPathType[1], -t, -u, -v);
    L_min = L;
  }

  // backwards
  double xb = x * std::cos(phi) + y * std::sin(phi), yb = x * std::sin(phi) - y * std::cos(phi);
  if (LpRmL(xb, yb, phi, t, u, v) && L_min > (L = std::abs(t) + std::abs(u) + std::abs(v))) {
    path =
      ReedsSheppStateSpace::ReedsSheppPath(ReedsSheppStateSpace::reedsSheppPathType[0], v, u, t);
    L_min = L;
  }
  if (
    LpRmL(-xb, yb, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // time flip
  {
    path =
      ReedsSheppStateSpace::ReedsSheppPath(ReedsSheppStateSpace::reedsSheppPathType[0], -v, -u, -t);
    L_min = L;
  }
  if (
    LpRmL(xb, -yb, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // reflect
  {
    path =
      ReedsSheppStateSpace::ReedsSheppPath(ReedsSheppStateSpace::reedsSheppPathType[1], v, u, t);
    L_min = L;
  }
  if (
    LpRmL(-xb, -yb, phi, t, u, v) &&
    L_min > (std::abs(t) + std::abs(u) + std::abs(v)))  // time flip + reflect
  {
    path =
      ReedsSheppStateSpace::ReedsSheppPath(ReedsSheppStateSpace::reedsSheppPathType[1], -v, -u, -t);
  }
}

inline bool LpRmL(double x, double y, double phi, double & t, double & u, double & v)
{
  double xi = x - std::sin(phi), eta = y - 1. + std::cos(phi), u1, theta;
  polar(xi, eta, u1, theta);
  if (u1 <= 4.) {
    u = -2. * std::asin(.25 * u1);
    t = mod2pi(theta + .5 * u + pi);
    v = mod2pi(phi - t + u);
    assert(std::abs(2 * (sin(t) - std::sin(t - u)) + std::sin(phi) - x) < RS_EPS);
    assert(std::abs(2 * (-cos(t) + std::cos(t - u)) - std::cos(phi) + 1 - y) < RS_EPS);
    assert(std::abs(mod2pi(t - u + v - phi)) < RS_EPS);
    return t >= -ZERO && u <= ZERO;
  }
  return false;
}

inline void polar(double x, double y, double & r, double & theta)
{
  r = std::sqrt(x * x + y * y);
  theta = std::atan2(y, x);
}

inline double mod2pi(double x)
{
  double v = std::fmod(x, twopi);
  if (v < -pi) {
    v += twopi;
  } else if (v > pi) {
    v -= twopi;
  }
  return v;
}

void CCCC(double x, double y, double phi, ReedsSheppStateSpace::ReedsSheppPath & path)
{
  double t, u, v, L_min = path.length(), L;
  if (
    LpRupLumRm(x, y, phi, t, u, v) && L_min > (L = std::abs(t) + 2. * std::abs(u) + std::abs(v))) {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[2], t, u, -u, v);
    L_min = L;
  }
  if (
    LpRupLumRm(-x, y, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + 2. * std::abs(u) + std::abs(v)))  // time flip
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[2], -t, -u, u, -v);
    L_min = L;
  }
  if (
    LpRupLumRm(x, -y, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + 2. * std::abs(u) + std::abs(v)))  // reflect
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[3], t, u, -u, v);
    L_min = L;
  }
  if (
    LpRupLumRm(-x, -y, phi, t, u, v) &&
    L_min > (L = std::abs(t) + 2. * std::abs(u) + std::abs(v)))  // time flip + reflect
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[3], -t, -u, u, -v);
    L_min = L;
  }

  if (
    LpRumLumRp(x, y, phi, t, u, v) && L_min > (L = std::abs(t) + 2. * std::abs(u) + std::abs(v))) {
    path =
      ReedsSheppStateSpace::ReedsSheppPath(ReedsSheppStateSpace::reedsSheppPathType[2], t, u, u, v);
    L_min = L;
  }
  if (
    LpRumLumRp(-x, y, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + 2. * std::abs(u) + std::abs(v)))  // time flip
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[2], -t, -u, -u, -v);
    L_min = L;
  }
  if (
    LpRumLumRp(x, -y, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + 2. * std::abs(u) + std::abs(v)))  // reflect
  {
    path =
      ReedsSheppStateSpace::ReedsSheppPath(ReedsSheppStateSpace::reedsSheppPathType[3], t, u, u, v);
    L_min = L;
  }
  if (
    LpRumLumRp(-x, -y, phi, t, u, v) &&
    L_min > (std::abs(t) + 2. * std::abs(u) + std::abs(v)))  // time flip + reflect
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[3], -t, -u, -u, -v);
  }
}

inline bool LpRupLumRm(double x, double y, double phi, double & t, double & u, double & v)
{
  double xi = x + std::sin(phi), eta = y - 1. - std::cos(phi),
         rho = .25 * (2. + sqrt(xi * xi + eta * eta));
  if (rho <= 1.) {
    u = acos(rho);
    tauOmega(u, -u, xi, eta, phi, t, v);
    assert(
      std::abs(2 * (sin(t) - std::sin(t - u) + std::sin(t - 2 * u)) - std::sin(phi) - x) < RS_EPS);
    assert(
      std::abs(2 * (-cos(t) + std::cos(t - u) - std::cos(t - 2 * u)) + std::cos(phi) + 1 - y) <
      RS_EPS);
    assert(std::abs(mod2pi(t - 2 * u - v - phi)) < RS_EPS);
    return t >= -ZERO && v <= ZERO;
  }
  return false;
}

inline void tauOmega(
  double u, double v, double xi, double eta, double phi, double & tau, double & omega)
{
  double delta = mod2pi(u - v);
  double A = std::sin(u) - std::sin(delta);
  double B = std::cos(u) - std::cos(delta) - 1.;
  double t1 = std::atan2(eta * A - xi * B, xi * A + eta * B);
  double t2 = 2. * (std::cos(delta) - std::cos(v) - std::cos(u)) + 3;
  tau = (t2 < 0) ? mod2pi(t1 + pi) : mod2pi(t1);
  omega = mod2pi(tau - u + v - phi);
}

inline double mod2pi(double x)
{
  double v = std::fmod(x, twopi);
  if (v < -pi) {
    v += twopi;
  } else if (v > pi) {
    v -= twopi;
  }
  return v;
}

inline bool LpRumLumRp(double x, double y, double phi, double & t, double & u, double & v)
{
  double xi = x + std::sin(phi), eta = y - 1. - std::cos(phi),
         rho = (20. - xi * xi - eta * eta) / 16.;
  if (rho >= 0 && rho <= 1) {
    u = -acos(rho);
    if (u >= -.5 * pi) {
      tauOmega(u, u, xi, eta, phi, t, v);
      assert(std::abs(4 * std::sin(t) - 2 * std::sin(t - u) - std::sin(phi) - x) < RS_EPS);
      assert(std::abs(-4 * std::cos(t) + 2 * std::cos(t - u) + std::cos(phi) + 1 - y) < RS_EPS);
      assert(std::abs(mod2pi(t - v - phi)) < RS_EPS);
      return t >= -ZERO && v >= -ZERO;
    }
  }
  return false;
}

inline void tauOmega(
  double u, double v, double xi, double eta, double phi, double & tau, double & omega)
{
  double delta = mod2pi(u - v);
  double A = std::sin(u) - std::sin(delta);
  double B = std::cos(u) - std::cos(delta) - 1.;
  double t1 = std::atan2(eta * A - xi * B, xi * A + eta * B);
  double t2 = 2. * (std::cos(delta) - std::cos(v) - std::cos(u)) + 3;
  tau = (t2 < 0) ? mod2pi(t1 + pi) : mod2pi(t1);
  omega = mod2pi(tau - u + v - phi);
}

inline double mod2pi(double x)
{
  double v = std::fmod(x, twopi);
  if (v < -pi) {
    v += twopi;
  } else if (v > pi) {
    v -= twopi;
  }
  return v;
}

void CCSC(double x, double y, double phi, ReedsSheppStateSpace::ReedsSheppPath & path)
{
  double t, u, v, L_min = path.length() - .5 * pi, L;
  if (LpRmSmLm(x, y, phi, t, u, v) && L_min > (L = std::abs(t) + std::abs(u) + std::abs(v))) {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[4], t, -.5 * pi, u, v);
    L_min = L;
  }
  if (
    LpRmSmLm(-x, y, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // time flip
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[4], -t, .5 * pi, -u, -v);
    L_min = L;
  }
  if (
    LpRmSmLm(x, -y, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // reflect
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[5], t, -.5 * pi, u, v);
    L_min = L;
  }
  if (
    LpRmSmLm(-x, -y, phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // time flip + reflect
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[5], -t, .5 * pi, -u, -v);
    L_min = L;
  }

  if (LpRmSmRm(x, y, phi, t, u, v) && L_min > (L = std::abs(t) + std::abs(u) + std::abs(v))) {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[8], t, -.5 * pi, u, v);
    L_min = L;
  }
  if (
    LpRmSmRm(-x, y, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // time flip
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[8], -t, .5 * pi, -u, -v);
    L_min = L;
  }
  if (
    LpRmSmRm(x, -y, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // reflect
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[9], t, -.5 * pi, u, v);
    L_min = L;
  }
  if (
    LpRmSmRm(-x, -y, phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // time flip + reflect
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[9], -t, .5 * pi, -u, -v);
    L_min = L;
  }

  // backwards
  double xb = x * std::cos(phi) + y * std::sin(phi), yb = x * std::sin(phi) - y * std::cos(phi);
  if (LpRmSmLm(xb, yb, phi, t, u, v) && L_min > (L = std::abs(t) + std::abs(u) + std::abs(v))) {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[6], v, u, -.5 * pi, t);
    L_min = L;
  }
  if (
    LpRmSmLm(-xb, yb, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // time flip
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[6], -v, -u, .5 * pi, -t);
    L_min = L;
  }
  if (
    LpRmSmLm(xb, -yb, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // reflect
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[7], v, u, -.5 * pi, t);
    L_min = L;
  }
  if (
    LpRmSmLm(-xb, -yb, phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // time flip + reflect
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[7], -v, -u, .5 * pi, -t);
    L_min = L;
  }

  if (LpRmSmRm(xb, yb, phi, t, u, v) && L_min > (L = std::abs(t) + std::abs(u) + std::abs(v))) {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[10], v, u, -.5 * pi, t);
    L_min = L;
  }
  if (
    LpRmSmRm(-xb, yb, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // time flip
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[10], -v, -u, .5 * pi, -t);
    L_min = L;
  }
  if (
    LpRmSmRm(xb, -yb, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // reflect
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[11], v, u, -.5 * pi, t);
    L_min = L;
  }
  if (
    LpRmSmRm(-xb, -yb, phi, t, u, v) &&
    L_min > (std::abs(t) + std::abs(u) + std::abs(v)))  // time flip + reflect
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[11], -v, -u, .5 * pi, -t);
  }
}

inline bool LpRmSmLm(double x, double y, double phi, double & t, double & u, double & v)
{
  double xi = x - std::sin(phi), eta = y - 1. + std::cos(phi), rho, theta;
  polar(xi, eta, rho, theta);
  if (rho >= 2.) {
    double r = sqrt(rho * rho - 4.);
    u = 2. - r;
    t = mod2pi(theta + std::atan2(r, -2.));
    v = mod2pi(phi - .5 * pi - t);
    assert(std::abs(2 * (sin(t) - std::cos(t)) - u * std::sin(t) + std::sin(phi) - x) < RS_EPS);
    assert(
      std::abs(-2 * (sin(t) + std::cos(t)) + u * std::cos(t) - std::cos(phi) + 1 - y) < RS_EPS);
    assert(std::abs(mod2pi(t + pi / 2 + v - phi)) < RS_EPS);
    return t >= -ZERO && u <= ZERO && v <= ZERO;
  }
  return false;
}

inline void polar(double x, double y, double & r, double & theta)
{
  r = std::sqrt(x * x + y * y);
  theta = std::atan2(y, x);
}

inline double mod2pi(double x)
{
  double v = std::fmod(x, twopi);
  if (v < -pi) {
    v += twopi;
  } else if (v > pi) {
    v -= twopi;
  }
  return v;
}

inline bool LpRmSmRm(double x, double y, double phi, double & t, double & u, double & v)
{
  double xi = x + std::sin(phi), eta = y - 1. - std::cos(phi), rho, theta;
  polar(-eta, xi, rho, theta);
  if (rho >= 2.) {
    t = theta;
    u = 2. - rho;
    v = mod2pi(t + .5 * pi - phi);
    assert(std::abs(2 * std::sin(t) - std::cos(t - v) - u * std::sin(t) - x) < RS_EPS);
    assert(std::abs(-2 * std::cos(t) - std::sin(t - v) + u * std::cos(t) + 1 - y) < RS_EPS);
    assert(std::abs(mod2pi(t + pi / 2 - v - phi)) < RS_EPS);
    return t >= -ZERO && u <= ZERO && v <= ZERO;
  }
  return false;
}

inline void polar(double x, double y, double & r, double & theta)
{
  r = std::sqrt(x * x + y * y);
  theta = std::atan2(y, x);
}

inline double mod2pi(double x)
{
  double v = std::fmod(x, twopi);
  if (v < -pi) {
    v += twopi;
  } else if (v > pi) {
    v -= twopi;
  }
  return v;
}

void CCSCC(double x, double y, double phi, ReedsSheppStateSpace::ReedsSheppPath & path)
{
  double t, u, v, L_min = path.length() - pi, L;
  if (LpRmSLmRp(x, y, phi, t, u, v) && L_min > (L = std::abs(t) + std::abs(u) + std::abs(v))) {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[16], t, -.5 * pi, u, -.5 * pi, v);
    L_min = L;
  }
  if (
    LpRmSLmRp(-x, y, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // time flip
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[16], -t, .5 * pi, -u, .5 * pi, -v);
    L_min = L;
  }
  if (
    LpRmSLmRp(x, -y, -phi, t, u, v) &&
    L_min > (L = std::abs(t) + std::abs(u) + std::abs(v)))  // reflect
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[17], t, -.5 * pi, u, -.5 * pi, v);
    L_min = L;
  }
  if (
    LpRmSLmRp(-x, -y, phi, t, u, v) &&
    L_min > (std::abs(t) + std::abs(u) + std::abs(v)))  // time flip + reflect
  {
    path = ReedsSheppStateSpace::ReedsSheppPath(
      ReedsSheppStateSpace::reedsSheppPathType[17], -t, .5 * pi, -u, .5 * pi, -v);
  }
}

inline bool LpRmSLmRp(double x, double y, double phi, double & t, double & u, double & v)
{
  double xi = x + std::sin(phi), eta = y - 1. - std::cos(phi), rho, theta;
  polar(xi, eta, rho, theta);
  if (rho >= 2.) {
    u = 4. - sqrt(rho * rho - 4.);
    if (u <= ZERO) {
      t = mod2pi(atan2((4 - u) * xi - 2 * eta, -2 * xi + (u - 4) * eta));
      v = mod2pi(t - phi);
      assert(
        std::abs(4 * std::sin(t) - 2 * std::cos(t) - u * std::sin(t) - std::sin(phi) - x) < RS_EPS);
      assert(
        std::abs(-4 * std::cos(t) - 2 * std::sin(t) + u * std::cos(t) + std::cos(phi) + 1 - y) <
        RS_EPS);
      assert(std::abs(mod2pi(t - v - phi)) < RS_EPS);
      return t >= -ZERO && v >= -ZERO;
    }
  }
  return false;
}

inline void polar(double x, double y, double & r, double & theta)
{
  r = std::sqrt(x * x + y * y);
  theta = std::atan2(y, x);
}

inline double mod2pi(double x)
{
  double v = std::fmod(x, twopi);
  if (v < -pi) {
    v += twopi;
  } else if (v > pi) {
    v -= twopi;
  }
  return v;
}

Trajectory create_trajectory(
  const PoseStamped & current_pose, const PlannerWaypoints & planner_waypoints,
  const double & velocity)
{
  Trajectory trajectory;
  trajectory.header = planner_waypoints.header;

  for (const auto & awp : planner_waypoints.waypoints) {
    TrajectoryPoint point;

    point.pose = awp.pose.pose;

    point.pose.position.z = current_pose.pose.position.z;  // height = const
    point.longitudinal_velocity_mps = velocity / 3.6;      // velocity = const

    // switch sign by forward/backward
    point.longitudinal_velocity_mps = (awp.is_back ? -1 : 1) * point.longitudinal_velocity_mps;

    trajectory.points.push_back(point);
  }

  return trajectory;
}

void FreespacePlannerNode::reset()
{
  trajectory_ = Trajectory();
  partial_trajectory_ = Trajectory();
  is_completed_ = false;
  std_msgs::msg::Bool is_completed_msg;
  is_completed_msg.data = is_completed_;
  parking_state_pub_->publish(is_completed_msg);
  obs_found_time_ = {};
}

Trajectory get_partial_trajectory(
  const Trajectory & trajectory, const size_t start_index, const size_t end_index,
  const rclcpp::Clock::SharedPtr clock)
{
  Trajectory partial_trajectory;
  partial_trajectory.header = trajectory.header;
  partial_trajectory.header.stamp = clock->now();

  partial_trajectory.points.reserve(trajectory.points.size());
  for (size_t i = start_index; i <= end_index; ++i) {
    partial_trajectory.points.push_back(trajectory.points.at(i));
  }

  // Modify velocity at start/end point
  if (partial_trajectory.points.size() >= 2) {
    partial_trajectory.points.front().longitudinal_velocity_mps =
      partial_trajectory.points.at(1).longitudinal_velocity_mps;
  }
  if (!partial_trajectory.points.empty()) {
    partial_trajectory.points.back().longitudinal_velocity_mps = 0;
  }

  return partial_trajectory;
}
